function promiseRace(list) {
  return new Promise((resolve, reject) => {
    for (const item of list) Promise.resolve(item).then(resolve, reject);
  });
}

const later = (ms, value) => new Promise((resolve) => setTimeout(resolve, ms, value));
const fail = (ms, text) => new Promise((resolve, reject) => setTimeout(reject, ms, new Error(text)));

promiseRace([later(30, "slow"), fail(10, "broken")]).catch((error) => console.log("lost: " + error.message));
promiseRace([later(30, "slow"), 7]).then((value) => console.log("won: " + value));
promiseRace([]).then(() => console.log("empty settled"));
setTimeout(() => console.log("end"), 50);
